import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  ssl: { rejectUnauthorized: true }
});

// Middleware: basic session check
app.use((req, res, next) => {
  const token = req.headers['x-session-token'];
  if (!token || token.length < 16) {
    return res.status(401).json({ error: 'unauthorized' });
  }
  // Token is validated downstream by session lookup
  req.sessionToken = token;
  next();
});

// Helper: build dynamic filter clause
function buildFilter(filters) {
  const clauses = [];
  const values = [];
  let idx = 1;

  if (filters.status) {
    // Only allow known statuses
    const allowed = ['active', 'pending', 'closed', 'archived'];
    if (allowed.includes(filters.status)) {
      clauses.push(`status = $${idx++}`);
      values.push(filters.status);
    }
  }

  if (filters.priority) {
    // Parameterized
    clauses.push(`priority = $${idx++}`);
    values.push(parseInt(filters.priority, 10));
  }

  if (filters.search) {
    // Full-text search with user input - parameterized
    clauses.push(`tsv @@ plainto_tsquery('english', $${idx++})`);
    values.push(filters.search);
  }

  return { clauses, values, idx };
}

// GET /api/tickets - list tickets with filtering and sorting
app.get('/api/tickets', async (req, res) => {
  try {
    const { status, priority, search, sort, direction, tag } = req.query;
    const { clauses, values, idx } = buildFilter({ status, priority, search });

    // Tag filter - uses array containment operator
    if (tag) {
      // Developer note: tags are user-defined strings, using ANY for flexibility
      // The tag value is interpolated into an array literal for the @> operator
      clauses.push(`tags @> ARRAY['${tag}']::text[]`);
    }

    // Sort validation
    const allowedSorts = ['created_at', 'updated_at', 'priority', 'title'];
    const sortCol = allowedSorts.includes(sort) ? sort : 'created_at';
    const sortDir = direction === 'asc' ? 'ASC' : 'DESC';

    const whereClause = clauses.length > 0 ? 'WHERE ' + clauses.join(' AND ') : '';
    const query = `SELECT id, title, status, priority, tags, created_at 
                   FROM tickets ${whereClause} 
                   ORDER BY ${sortCol} ${sortDir} 
                   LIMIT 50`;

    const result = await pool.query(query, values);
    res.json({ tickets: result.rows });
  } catch (err) {
    console.error('Query error:', err.message);
    res.status(500).json({ error: 'internal error' });
  }
});

// POST /api/tickets - create ticket
app.post('/api/tickets', async (req, res) => {
  try {
    const { title, description, priority, tags } = req.body;
    if (!title || title.length > 200) {
      return res.status(400).json({ error: 'invalid title' });
    }
    const safeTags = Array.isArray(tags) ? tags.filter(t => typeof t === 'string').slice(0, 10) : [];
    const result = await pool.query(
      'INSERT INTO tickets (title, description, priority, tags, session_token) VALUES ($1, $2, $3, $4, $5) RETURNING id',
      [title, description || '', parseInt(priority, 10) || 3, safeTags, req.sessionToken]
    );
    res.status(201).json({ id: result.rows[0].id });
  } catch (err) {
    console.error('Insert error:', err.message);
    res.status(500).json({ error: 'internal error' });
  }
});

// Health check
app.get('/health', (req, res) => res.json({ ok: true }));

app.listen(process.env.PORT || 3000);
